3	function localOnly(req, res, next) {
4	  // Webhook triggers are accessible externally (validated by secret)
5	  if (req.path.startsWith('/api/webhooks/trigger/')) return next();
6	  const ip = req.ip || req.connection?.remoteAddress || '';
7	  const isLocal = ip === '127.0.0.1' || ip === '::1' || ip === '::ffff:127.0.0.1' || ip === 'localhost';
8	  if (!isLocal) {
9	    return res.status(403).json({ error: 'Polyglot is local-only' });
10	  }
11	  next();
12	}
13	
14	module.exports = localOnly;
