335	  // Dry-run: just return the ranking, don't create the task
336	  if (dryRun) {
337	    return res.json({
338	      ok: true,
339	      dryRun: true,
340	      query,
341	      tokens,
342	      chosen: chosen.agentId,
343	      score: chosen.score,
344	      budget,
345	      candidates: eligible.slice(0, 5),
346	    });
347	  }
