456	export async function callAgent(agentName, prompt, timeoutMs = 120000) {
457	  const controller = new AbortController()
458	  const timeout = setTimeout(() => controller.abort(), timeoutMs)
459	
460	  try {
461	    const response = await fetch(\`\${POLYGLOT_URL}/api/playground/run\`, {
462	      method: 'POST',
463	      headers: { 'Content-Type': 'application/json' },
464	      body: JSON.stringify({ agentName, prompt }),
465	      signal: controller.signal,
466	    })
467	    clearTimeout(timeout)
468	    if (!response.ok) throw new Error(\`Polyglot returned \${response.status}\`)
469	
470	    const text = await response.text()
471	    const events = text
472	      .split('\\n')
473	      .filter(line => line.startsWith('data: '))
474	      .map(line => { try { return JSON.parse(line.slice(6)) } catch { return null } })
475	      .filter(Boolean)
476	
477	    const errorEvent = events.find(e => e.type === 'error')
478	    if (errorEvent) return { success: false, output: '', agent: agentName, error: errorEvent.error }
479	
480	    const doneEvent = events.find(e => e.type === 'done' || e.type === 'complete')
481	    return { success: true, output: doneEvent?.output || '', agent: agentName }
482	  } catch (err) {
483	    clearTimeout(timeout)
484	    const msg = err instanceof Error ? err.message : String(err)
485	    return {
486	      success: false,
487	      output: '',
488	      agent: agentName,
489	      error: msg.includes('abort')
490	        ? \`Timed out after \${timeoutMs / 1000}s\`
491	        : \`Polyglot not reachable — is it running?\`,
492	    }
493	  }
494	}
